package com.chillpavz.seamlessores.content;

import com.chillpavz.seamlessores.Constants;

import java.util.ArrayList;
import java.util.List;

/**
 * Which other mods' ores each stone swallows, as measured by the pair model: every ore that reaches the
 * stone at a rate above the floor, in a band and on a loader where both mods exist. The geology rule
 * (OreGeology) then decides which of them get a variant.
 *
 * <p>GENERATED by tools/&lt;band&gt;/generate_assets.py from tools/&lt;band&gt;/modded_pairs.json. Do not edit.
 */
final class ModdedPairs {

    private ModdedPairs() {}

    /** The modded ores the stone with this id swallows; none for a stone with no modded pairs. */
    static List<OreType> of(String host) {
        return switch (host) {
            default -> List.of();
        };
    }

    private static List<OreType> keys(String... keys) {
        final List<OreType> ores = new ArrayList<>(keys.length);
        for (String key : keys) {
            final OreType ore = OreType.byKey(key);
            if (ore == null) {
                Constants.LOG.error("The modded pairs name an ore key {} the ore table does not have", key);
            } else {
                ores.add(ore);
            }
        }
        return ores;
    }
}
